// Pega o CSV como texto vindo do HTTP Request
const csvRaw = $json.data ?? $json.body ?? $json;
const text = (typeof csvRaw === "string") ? csvRaw : JSON.stringify(csvRaw);

const lines = text.split(/\r?\n/).map(l => l.trim()).filter(Boolean);
const headers = lines[0].split(",").map(h => h.trim());

const investimentos = lines.slice(1).map(line => {
  const cols = line.split(",").map(c => c.trim());
  const obj = {};
  headers.forEach((h, i) => obj[h] = cols[i] ?? "");

  // normaliza mínimo para número
  obj.minimo = Number(String(obj.minimo).replace(/[^\d]/g, "")) || 0;

  return obj;
});

return [{ json: { investimentos } }];

// Dados vindos do nó anterior (webhook + investimentos)
const data = $input.first().json;
const clientes = data.body?.clientes ?? data.clientes ?? [];
const investimentos = data.investimentos ?? [];

// "R$ 12.500,00" -> 12500
function parseSaldo(valor) {
  if (typeof valor === "number") return valor;
  const limpo = String(valor)
    .replace(/[^\d,]/g, "")   // mantém só dígitos e vírgula
    .replace(",", ".");       // vírgula decimal -> ponto
  return Number(limpo) || 0;
}

// 12500 -> "R$ 12.500,00"
function formatBRL(valor) {
  return valor.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });
}

// Mensagem de abertura para cada perfil
const introPorPerfil = {
  Conservador: "Sabemos que segurança e tranquilidade vêm em primeiro lugar para você. Por isso, selecionamos opções de baixo risco e boa liquidez:",
  Moderado: "Você busca equilíbrio entre segurança e rentabilidade. Separamos opções que diversificam sua carteira sem abrir mão do controle:",
  Arrojado: "Você tem apetite para buscar retornos maiores no longo prazo. Confira oportunidades com maior potencial de valorização:",
};

// Descrição curta para cada tipo de investimento
const descricaoPorProduto = {
  "Poupança": "simples, isenta de IR e com resgate a qualquer momento",
  "CDB Liquidez Diária": "rende mais que a poupança e você resgata quando quiser",
  "Tesouro Selic": "título público, ideal para reserva de emergência",
  "CDB Prefixado": "você já sabe na aplicação quanto vai receber no vencimento",
  "Fundo Multimercado": "gestão profissional combinando renda fixa, ações e câmbio",
  "Tesouro IPCA+": "protege seu dinheiro da inflação com ganho real",
  "Ações ETF": "diversificação na bolsa com um único ativo e custo baixo",
  "Fundo de Ações": "carteira de ações escolhida por gestores especialistas",
  "Criptomoedas": "alta volatilidade, indicada só para uma pequena parte da carteira",
};

// Aviso final para cada perfil
const avisoPorPerfil = {
  Conservador: "Quer ajuda para montar sua reserva de emergência? É só responder este e-mail.",
  Moderado: "Podemos agendar uma conversa para ajustar a diversificação da sua carteira.",
  Arrojado: "Lembre-se: investimentos de renda variável podem oscilar e não têm rentabilidade garantida.",
};

return clientes.map(cliente => {
  const saldo = parseSaldo(cliente.saldo);
  const primeiroNome = cliente.nome.split(" ")[0];

  // Filtra pelo perfil do cliente e pelo saldo disponível
  const elegiveis = investimentos.filter(inv =>
    inv.perfil === cliente.perfil && Number(inv.minimo) <= saldo
  );

  const bloqueados = investimentos.filter(inv =>
    inv.perfil === cliente.perfil && Number(inv.minimo) > saldo
  );

  let mensagem;

  if (elegiveis.length === 0) {
    mensagem =
      `Olá, ${primeiroNome}!\n\n` +
      `Com seu saldo atual de ${formatBRL(saldo)}, ainda não há produtos do perfil ${cliente.perfil} ` +
      `disponíveis para você. Que tal começar a poupar um pouco por mês? Estamos aqui para ajudar.\n\n` +
      `Equipe de Investimentos`;
  } else {
    const lista = elegiveis
      .map(inv =>
        `• ${inv.produto} — rentabilidade: ${inv.rentabilidade} | mínimo: ${formatBRL(Number(inv.minimo))}\n` +
        `  ${descricaoPorProduto[inv.produto] ?? ""}`
      )
      .join("\n");

    const extra = bloqueados.length
      ? `\n\nAo atingir o valor mínimo, você também poderá investir em: ` +
        bloqueados.map(inv => `${inv.produto} (a partir de ${formatBRL(Number(inv.minimo))})`).join(", ") + "."
      : "";

    mensagem =
      `Olá, ${primeiroNome}!\n\n` +
      `${introPorPerfil[cliente.perfil] ?? "Confira as opções disponíveis para você:"}\n\n` +
      `${lista}` +
      `${extra}\n\n` +
      `Seu saldo disponível: ${formatBRL(saldo)}\n\n` +
      `${avisoPorPerfil[cliente.perfil] ?? ""}\n\n` +
      `Equipe de Investimentos`;
  }

  return {
    json: {
      nome: cliente.nome,
      email: cliente.email,
      perfil: cliente.perfil,
      saldo,
      assunto: `${primeiroNome}, investimentos selecionados para o seu perfil ${cliente.perfil}`,
      mensagem,
      recomendados: elegiveis.map(inv => inv.produto),
    },
  };
});

// Aceita tanto vários itens quanto um único item contendo um array
const entrada = $input.all().flatMap(item =>
  Array.isArray(item.json) ? item.json : [item.json]
);

// Remove espaços extras
const limpar = v => String(v ?? "").replace(/\s+/g, " ").trim();

// "ana silva" -> "Ana Silva"
const capitalizar = v =>
  limpar(v)
    .toLowerCase()
    .replace(/(^|\s)\p{L}/gu, letra => letra.toUpperCase());

// Aceita número ou "R$ 12.500,00"
function parseValor(v) {
  if (typeof v === "number") return v;
  return Number(String(v).replace(/[^\d,]/g, "").replace(",", ".")) || 0;
}

const formatBRL = v =>
  v.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });

const emailValido = e => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e);

// Escapa caracteres especiais e converte quebras de linha para HTML
function textoParaHtml(texto) {
  return texto
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .split(/\n{2,}/)
    .map(paragrafo => `<p>${paragrafo.replace(/\n/g, "<br>")}</p>`)
    .join("\n");
}

const vistos = new Set();
const resultado = [];

for (const c of entrada) {
  const email = limpar(c.email).toLowerCase();

  // Ignora e-mails duplicados
  if (vistos.has(email)) continue;
  vistos.add(email);

  const nome = capitalizar(c.nome);
  const saldo = parseValor(c.saldo);
  const recomendados = (c.recomendados ?? []).map(limpar).filter(Boolean);
  const mensagemTexto = String(c.mensagem ?? "").replace(/\r\n/g, "\n").trim();

  resultado.push({
    json: {
      nome,
      primeiroNome: nome.split(" ")[0],
      email,
      emailValido: emailValido(email),
      perfil: capitalizar(c.perfil),
      perfilId: limpar(c.perfil).toLowerCase(), // "conservador", "moderado", "arrojado"
      saldo,
      saldoFormatado: formatBRL(saldo),
      assunto: limpar(c.assunto),
      mensagemTexto,
      mensagemHtml: textoParaHtml(mensagemTexto),
      recomendados,
      recomendadosTexto: recomendados.join(", "),
      totalRecomendados: recomendados.length,
      geradoEm: new Date().toISOString(),
    },
  });
}

return resultado;
